content.CONV_H_MISSION_2B:
[
  {
    "idNpc": 0,
    "text": "Sono già connesso, cosa c'è che non va?"
  },
  {
    "idNpc": 1,
    "text": "Sono molto nervoso... sai già come farai?"
  },
  {
    "idNpc": 0,
    "text": "Sì, accidenti, ho già comprato quello che mi serviva ed è già tutto sistemato; è stato veloce, proprio come avevamo concordato."
  },
  {
    "idNpc": 1,
    "text": "Già?? È passato tutto così in fretta, pensavo che ci avresti messo qualche giorno."
  },
  {
    "idNpc": 0,
    "text": "Ti avevo già avvertito che non si poteva tornare indietro e tu mi hai detto che andava bene."
  },
  {
    "idNpc": 0,
    "text": "Ho intravisto l'occasione per portare a termine il lavoro in modo impeccabile e l'ho colta al volo."
  },
  {
    "idNpc": 1,
    "text": "Quindi è..."
  },
  {
    "idNpc": 0,
    "text": "Morto, sì, proprio come volevi"
  },
  {
    "idNpc": 0,
    "text": "Ma che diavolo ti prende?"
  },
  {
    "idNpc": 0,
    "text": "A proposito, ti ricordo che devi pagarmi. Non credo che tu abbia problemi con quanto ti daranno per l’assicurazione sulla vita"
  },
  {
    "idNpc": 1,
    "text": "Quando lo riceverò, ti pagherò e non ci parleremo mai più."
  },
  {
    "idNpc": 0,
    "text": "Lo spero proprio"
  }
]

