content.CONV_H_MISSION_4:
[
  {
    "idNpc": 1,
    "text": "Ciao! Sono appena arrivato in città"
  },
  {
    "idNpc": 1,
    "text": "Sei occupato? Ti offro una birra."
  },
  {
    "idNpc": 0,
    "text": "Caspita, da quanto tempo non ho tue notizie?"
  },
  {
    "idNpc": 0,
    "text": "Ho delle cose interessanti da raccontarti, anzi, ti invito a bere quella birra"
  },
  {
    "idNpc": 1,
    "text": "Ah! Stai invitando qualcosa?"
  },
  {
    "idNpc": 1,
    "text": "E quale povero diavolo stai tormentando questa volta?"
  },
  {
    "idNpc": 0,
    "text": "Sto hackerando un perdente, ho il numero del suo conto corrente"
  },
  {
    "idNpc": 1,
    "text": "Non so se ti credo, ma finché mi compri quella birra non mi interessa xD"
  },
  {
