  }
]

content.CONV_H_MISSION_4B:
[
  {
    "idNpc": 0,
    "text": "Potrebbe sembrare una domanda strana..."
  },
  {
    "idNpc": 0,
    "text": "Conosci qualcuno che sia esperto di sicurezza informatica?"
  },
  {
    "idNpc": 1,
    "text": ":O"
  },
  {
    "idNpc": 1,
    "text": "No, mi dispiace."
  },
  {
    "idNpc": 1,
    "text": "Che cosa è successo?"
  },
  {
    "idNpc": 0,
    "text": "C'è un tizio che mi ha hackerato diverse volte..."
  },
  {
    "idNpc": 0,
    "text": "Ho formattato il sistema, ma quel tizio continua a intromettersi"
  },
  {
    "idNpc": 0,
    "text": "La goccia che ha fatto traboccare il vaso è stata quando ha scoperto la mia password bancaria e mi ha rubato dei soldi"
  },
  {
    "idNpc": 1,
    "text": "Uff... È una cosa molto seria"
  },
  {
    "idNpc": 1,
    "text": "Hai chiamato la polizia?"
  },
  {
    "idNpc": 0,
    "text": "No... quel tizio mi ricatta dicendomi che se lo dico alla polizia le cose andranno molto peggio"
  },
  {
    "idNpc": 0,
    "text": "Dice di avere amici come lui, e che non esiteranno a prendersela con me se lo denuncio"
  },
  {
    "idNpc": 1,
    "text": "Che sistema operativo usi?"
  },
  {
    "idNpc": 0,
    "text": "Quella che usano quasi tutti, Ellipse"
  },
  {
    "idNpc": 1,
    "text": "Se fossi in te, penserei di cambiare sistema operativo... ultimamente ha la reputazione di essere poco sicuro"
  },
  {
    "idNpc": 1,
    "text": "Forse quel tipo sta bluffando ed è solo un ragazzino che usa qualche codice che ha trovato su Internet"
  },
  {
    "idNpc": 0,
    "text": "Non so se installare un altro sistema operativo risolverà il problema, ma immagino che provarci non mi costi nulla"
  }
]

content.CONV_H_MISSION_4C:
[
  {
    "idNpc": 0,
    "text": "Ciao, sono di nuovo io"
  },
  {
    "idNpc": 0,
    "text": "xDD"
  },
  {
    "idNpc": 1,
    "text": "..."
