    "idNpc": 0,
    "text": "Sei così stupido da non aver ancora capito chi sono?"
  },
  {
    "idNpc": 1,
    "text": "Non capisco proprio niente"
  },
  {
    "idNpc": 1,
    "text": "Ti conosco?"
  },
  {
    "idNpc": 1,
    "text": "Dimmi chi sei e perché non la smetti di hackerare il mio computer?"
  },
  {
    "idNpc": 0,
    "text": "Sono $NPC_IDX0"
  },
  {
    "idNpc": 0,
    "text": "Niente?"
  },
  {
    "idNpc": 0,
    "text": "Abbiamo lavorato insieme nella stessa azienda per 10 anni."
  },
  {
    "idNpc": 0,
    "text": "Finché non hai deciso di diffondere la voce che picchio i miei figli e chissà quali altre follie"
  },
  {
    "idNpc": 0,
    "text": "Sapevi che, quando stavano per scegliere uno dei due per la promozione, non avrebbero aspettato che la situazione si chiarisse del tutto"
  },
  {
    "idNpc": 0,
    "text": "Beh, complimenti, signor amministratore delegato, ha fatto licenziare anche me"
  },
  {
    "idNpc": 1,
    "text": "Non capisco di cosa stai parlando"
  },
  {
    "idNpc": 0,
    "text": "Ci conosciamo molto bene ed entrambi sappiamo che sei stato tu."
  },
  {
    "idNpc": 1,
    "text": "Hai delle prove a sostegno di ciò?"
  },
  {
    "idNpc": 0,
    "text": "Certo che no"
  },
  {
    "idNpc": 0,
    "text": "Ma ti assicuro che te ne pentirai"
  },
  {
    "idNpc": 0,
    "text": "Al momento sono riuscito ad accedere al tuo conto corrente e ho effettuato alcuni bonifici"
  },
  {
    "idNpc": 1,
    "text": "Chiamerò la polizia"
  },
  {
    "idNpc": 0,
    "text": "Non te lo consiglio: ho trovato alcuni documenti sul tuo computer che potrebbero metterti nei guai con la polizia"
  },
  {
    "idNpc": 1,
    "text": "Dimmi cosa vuoi"
  },
  {
    "idNpc": 0,
    "text": "Non preoccuparti, non appena avrò finito la lista te la manderò."
  }
]

